/**
 * Season-to-season rating progression, fitted on real careers (CricketArchive per-year T20 ratings).
 * The parameters live in progression-model.ts (generated by packages/ratings/src/analysis/progression.py);
 * this file is the sampler built on them. See docs/RATINGS-PIPELINE.md, "Progression model".
 *
 * A discipline's (batting or bowling) overall moves by
 *   mean(age, level, last change, experience, kind) + sd(age, experience) * z
 * where z is drawn from the empirical standardised residuals, so breakouts and collapses occur at their real
 * frequency, and the level term pulls players coming off outlier seasons back toward the mean.
 */

import { PROGRESSION_MODEL, type DisciplineFit } from "./progression-model.js";
import { normSInv } from "./math.js";
import type { RNG } from "./rng.js";

export type ProgressionGender = "male" | "female";
export type Discipline = "bat" | "bowl";
export type BatKind = "top" | "middle" | "lower";
export type BowlKind = "pace" | "spin" | "unknown";
export type RetirementRole = "bat" | "pace" | "spin" | "allround";

/** Mean rating of the discipline a player is not mainly picked for (game scale), the level it regresses toward */
export const PERIPHERAL_MEAN: Record<Discipline, number> = { bat: 42, bowl: 35 };
/** The secondary discipline of a specialist moves less than a regular's; judgement, not fitted (CA values for
 *  players who barely bat or bowl are heavily shrunk estimates on a different scale than the game's) */
export const PERIPHERAL_SD_SCALE = 0.6;
export const PERIPHERAL_DRIFT_SCALE = 0.5;
export const PERIPHERAL_REVERSION = 0.08;
/** The age (after the birthday) the age effects are measured against for secondary disciplines */
const PRIME_AGE = 27.5;
const EXP_CAP = 15;

export function interp(xs: readonly number[], ys: readonly number[], x: number): number {
  if (x <= xs[0]) return ys[0];
  const last = xs.length - 1;
  if (x >= xs[last]) return ys[last];
  for (let i = 1; i <= last; i++) {
    if (x <= xs[i]) {
      const t = (x - xs[i - 1]) / (xs[i] - xs[i - 1]);
      return ys[i - 1] + (ys[i] - ys[i - 1]) * t;
    }
  }
  return ys[last];
}

/** Draw a standardised residual (mean 0, sd 1) with the fitted, fat-tailed shape */
export function sampleResidual(discipline: Discipline, rng: RNG): number {
  const probs = PROGRESSION_MODEL.zProbs;
  const q = PROGRESSION_MODEL.zQuantiles[discipline];
  const u = Math.min(1 - 1e-9, Math.max(1e-9, rng()));
  const last = probs.length - 1;
  let z: number;
  if (u <= probs[0]) z = q[0] + (normSInv(u) - normSInv(probs[0]));
  else if (u >= probs[last]) z = q[last] + (normSInv(u) - normSInv(probs[last]));
  else {
    let i = 1;
    while (probs[i] < u) i++;
    z = q[i - 1] + (q[i] - q[i - 1]) * ((u - probs[i - 1]) / (probs[i] - probs[i - 1]));
  }
  return Math.max(-6, Math.min(6, z));
}

export interface DisciplineState {
  /** Current overall of the discipline (0-99) */
  ovr: number;
  /** Overall a season ago, when known (feeds the give-back-after-a-jump term) */
  prevOvr?: number;
  /** Batting position group for batting; pace / spin for bowling */
  kind?: BatKind | BowlKind;
  /** Whether this is a discipline the player is picked for. Secondary disciplines move less. */
  regular: boolean;
}

export interface ProgressionState {
  gender: ProgressionGender;
  /** Age after the coming birthday (the age the player will be next season) */
  age: number;
  /** Seasons of rating evidence so far (1 for a debutant) */
  experience: number;
  bat: DisciplineState;
  bowl: DisciplineState;
}

function fitFor(discipline: Discipline, gender: ProgressionGender): DisciplineFit {
  return PROGRESSION_MODEL[discipline][gender];
}

function kindOffset(fit: DisciplineFit, discipline: Discipline, kind?: string): number {
  if (!kind) return 0;
  if (discipline === "bowl" && kind === "unknown") return (fit.kind.spin ?? 0) / 2;
  return fit.kind[kind] ?? 0;
}

/** Expected change of a regular discipline's overall, before any luck */
export function expectedChange(discipline: Discipline, gender: ProgressionGender, s: ProgressionState): number {
  const fit = fitFor(discipline, gender);
  const d = discipline === "bat" ? s.bat : s.bowl;
  const o = d.ovr;
  const mom = d.prevOvr === undefined ? 0 : o - d.prevOvr;
  let mean = interp(fit.ageNodes, fit.ageEffect, s.age)
    + fit.slope * (o - 65) + fit.slopeHigh * Math.max(0, o - 80) + fit.slopeLow * Math.min(0, o - 50)
    + fit.momentum * mom + fit.expCoef * Math.log(Math.min(Math.max(1, s.experience), EXP_CAP))
    + kindOffset(fit, discipline, d.kind);
  if (!d.regular) {
    const prime = interp(fit.ageNodes, fit.ageEffect, PRIME_AGE);
    mean = PERIPHERAL_DRIFT_SCALE * (interp(fit.ageNodes, fit.ageEffect, s.age) - prime)
      - PERIPHERAL_REVERSION * (o - PERIPHERAL_MEAN[discipline]);
  }
  return mean;
}

/** Spread (sd, in rating points) of next season's change */
export function changeSd(discipline: Discipline, gender: ProgressionGender, s: ProgressionState): number {
  const fit = fitFor(discipline, gender);
  const d = discipline === "bat" ? s.bat : s.bowl;
  const sd = fit.sdBase * interp(fit.ageNodes, fit.sdAge, s.age) * interp(fit.expNodes, fit.sdExp, Math.max(1, s.experience));
  return d.regular ? sd : sd * PERIPHERAL_SD_SCALE;
}

/** One season's change of a discipline's overall (rating points, unrounded) */
export function sampleChange(
  discipline: Discipline, s: ProgressionState, rng: RNG, opts: { volatility?: number; extraDrift?: number } = {},
): number {
  const mean = expectedChange(discipline, s.gender, s) + (opts.extraDrift ?? 0);
  const sd = changeSd(discipline, s.gender, s) * (opts.volatility ?? 1);
  return mean + sd * sampleResidual(discipline, rng);
}

/**
 * Expected overall of a discipline at `peakAge`, following the mean path with no luck (`s.age` is the age after the
 * coming birthday, so the first step is the one into that age).
 * Used to turn a drawn talent into a `potential` and to steer prospects toward it.
 */
export function meanPathOvr(discipline: Discipline, s: ProgressionState, peakAge = 27): number {
  let cur: ProgressionState = {
    ...s, bat: { ...s.bat }, bowl: { ...s.bowl },
  };
  const side = (st: ProgressionState) => (discipline === "bat" ? st.bat : st.bowl);
  while (cur.age <= peakAge) {
    const prev = side(cur).ovr;
    const delta = expectedChange(discipline, cur.gender, cur);
    const next = Math.max(1, Math.min(99, prev + delta));
    const d: DisciplineState = { ...side(cur), ovr: next, prevOvr: prev };
    cur = { ...cur, age: cur.age + 1, experience: cur.experience + 1, [discipline]: d } as ProgressionState;
  }
  return side(cur).ovr;
}

/** Standard deviation of the mature rating (age ~27) that growing up leaves unexplained, by experience at the start */
export function peakSpread(experience: number): number {
  // total sd of an 8-year random walk of the fitted innovations, damped by regression to the mean (~12%/season)
  return experience <= 2 ? 7.5 : experience <= 5 ? 6 : 4.5;
}

// ---------------------------------------------------------------------------------------------------- retirement

export function retirementRole(bowlingStyle: string, role: string): RetirementRole {
  if (role === "all-rounder") return "allround";
  if (role === "bowler") return /spin|orthodox|wrist/.test(bowlingStyle) ? "spin" : "pace";
  return "bat";
}

/**
 * Chance that a player's current season is his last in T20 (never plays again within four seasons), from the
 * real careers of regulars: by age, level, role and gender.
 */
export function retirementProbability(input: {
  age: number; overall: number; role: RetirementRole; gender?: ProgressionGender;
}): number {
  const r = PROGRESSION_MODEL.retirement;
  const centres = r.bins.map(([lo, hi]) => (hi >= 99 ? 43 : lo === 0 ? 20 : (lo + hi) / 2));
  let logit = interp(centres, r.ageEffect, input.age) + r.level * (input.overall - 65) / 10 + (r.role[input.role] ?? 0);
  if (input.gender === "female") logit += r.female;
  const p = 1 / (1 + Math.exp(-logit));
  return Math.min(0.9, Math.max(0.003, p));
}

// ---------------------------------------------------------------------------------------------------- experience

/** Seasons of rating evidence a real player probably has, from age and T20 matches played */
export function estimateExperience(age: number, careerMatches = 0): number {
  const bySchedule = Math.ceil(careerMatches / 14);
  return Math.max(1, Math.min(EXP_CAP, age - 17, careerMatches > 0 ? bySchedule : age - 19));
}
